import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"05 - Security Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/database-layer.md","filePath":"developers/design-documentation/database-layer.md"}'),s={name:"developers/design-documentation/database-layer.md"};function o(n,e,d,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="_05-security-architecture" tabindex="-1">05 - Security Architecture <a class="header-anchor" href="#_05-security-architecture" aria-label="Permalink to &quot;05 - Security Architecture&quot;">​</a></h1><h2 id="trust-boundaries" tabindex="-1">Trust Boundaries <a class="header-anchor" href="#trust-boundaries" aria-label="Permalink to &quot;Trust Boundaries&quot;">​</a></h2><p>Tradeboard is a self-hosted trading application. The application enforces authentication, request validation, rate limits, IP bans, browser protections, and encrypted token persistence. The operator owns host hardening, TLS termination, reverse-proxy trust, firewall policy, secrets, backups, and broker-account controls.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client</span></span>
<span class="line"><span>  -&gt; TLS/reverse proxy and host firewall</span></span>
<span class="line"><span>  -&gt; Flask security and IP-ban middleware</span></span>
<span class="line"><span>  -&gt; session, API-key, webhook, or OAuth authentication</span></span>
<span class="line"><span>  -&gt; schema/CSRF/rate-limit policy</span></span>
<span class="line"><span>  -&gt; service and broker/sandbox boundary</span></span>
<span class="line"><span>  -&gt; isolated local stores</span></span></code></pre></div><p>The internal ZeroMQ market-data endpoint is unauthenticated and must remain private. The public market-data WebSocket has its own API-key authentication handshake.</p><h2 id="application-authentication" tabindex="-1">Application Authentication <a class="header-anchor" href="#application-authentication" aria-label="Permalink to &quot;Application Authentication&quot;">​</a></h2><p>Application passwords are Argon2-hashed with <code>API_KEY_PEPPER</code>. TOTP can be required independently for login, Remote MCP write authorization, and password reset.</p><p>Device sessions and the installation-wide broker session are separate:</p><ul><li>at most five active application sessions are retained per user;</li><li>same-user/same-IP login replaces the existing device row;</li><li>session-status polling refreshes <code>last_seen</code> no more than once every 30 seconds;</li><li>broker-token expiry preserves a valid app session and reports reconnect state;</li><li>password changes revoke active device sessions.</li></ul><p>The default daily session boundary is <code>03:00</code> IST. <code>DISABLE_SESSION_EXPIRY=true</code> supports deliberately continuous deployments such as crypto, but it expands session lifetime and should be an explicit decision.</p><h2 id="api-keys-and-tokens" tabindex="-1">API Keys And Tokens <a class="header-anchor" href="#api-keys-and-tokens" aria-label="Permalink to &quot;API Keys And Tokens&quot;">​</a></h2><p>Tradeboard generates one current 64-character hexadecimal API key per user. <code>database/auth_db.py</code> stores:</p><ul><li>an Argon2 hash for verification;</li><li>an encrypted copy for authenticated UI and integration retrieval;</li><li>hashed cache keys for positive and negative verification caches.</li></ul><p>Regeneration invalidates the prior key. The key has no per-operation scopes; public REST operations remain subject to schemas, Analyzer Mode, Action Center policy, services, and rate limits.</p><p>Broker auth/feed tokens and other supported token fields use Fernet. The key is derived from <code>API_KEY_PEPPER</code> and the per-install <code>FERNET_SALT</code>. A legacy static-salt fallback exists only for migration compatibility and must not be documented as the normal installation design.</p><p>Static broker application credentials remain in <code>.env</code>; masking them in Profile responses does not encrypt that file.</p><h2 id="browser-and-rest-policy" tabindex="-1">Browser And REST Policy <a class="header-anchor" href="#browser-and-rest-policy" aria-label="Permalink to &quot;Browser And REST Policy&quot;">​</a></h2><ul><li>HTTPS deployments use Secure, HTTP-only, SameSite session cookies and the <code>__Secure-</code> prefix where configured.</li><li>Session-authenticated state changes use CSRF protection unless a route has a specific callback/webhook exemption.</li><li><code>/api/v1</code> is CSRF-exempt because it uses API-key request authentication.</li><li>CORS, CSP, referrer, permissions, framing, and related response headers are configured centrally.</li><li>Debug mode is rejected on externally bound hosts unless the operator explicitly overrides the guard.</li></ul><p>Most REST schemas require <code>apikey</code> in the JSON body. Only endpoints that explicitly implement another location should accept a header or query parameter.</p><h2 id="ip-security" tabindex="-1">IP Security <a class="header-anchor" href="#ip-security" aria-label="Permalink to &quot;IP Security&quot;">​</a></h2><p><code>SecurityMiddleware</code> checks the resolved client IP against <code>logs.db</code> before Flask handles the request. <code>TRUST_PROXY_HEADERS</code> is false by default; forwarded headers are accepted only when it is enabled. Enabling it without an enforced reverse-proxy boundary permits IP spoofing.</p><p>Automatic banning is persisted in application settings and is off by default:</p><table tabindex="0"><thead><tr><th>Setting</th><th style="text-align:right;">Default</th></tr></thead><tbody><tr><td>404 threshold in 24 hours</td><td style="text-align:right;">100</td></tr><tr><td>404 ban duration</td><td style="text-align:right;">0 hours (permanent)</td></tr><tr><td>Invalid API-key threshold in 24 hours</td><td style="text-align:right;">100</td></tr><tr><td>Invalid API-key ban duration</td><td style="text-align:right;">0 hours (permanent)</td></tr><tr><td>Repeat-offender limit</td><td style="text-align:right;">2 bans</td></tr></tbody></table><p>Localhost addresses are excluded from automatic bans. There is no general CIDR allowlist in the application middleware. See <a href="./23-ip-security.html">23 IP Security</a>.</p><h2 id="traffic-and-audit-boundaries" tabindex="-1">Traffic And Audit Boundaries <a class="header-anchor" href="#traffic-and-audit-boundaries" aria-label="Permalink to &quot;Traffic And Audit Boundaries&quot;">​</a></h2><p>Traffic logging stores timestamp, client IP, method, path, status, duration, host, optional middleware error, and user ID when available. It does not store request/response bodies, headers, user agents, or a processing timeline.</p><p>Order, analyzer, login, MCP, latency, health, and notification events use separate persistence or logging paths. <code>logs.db</code> traffic rows are therefore not a complete audit trail of every state change.</p><h2 id="websocket-and-mcp-security" tabindex="-1">WebSocket And MCP Security <a class="header-anchor" href="#websocket-and-mcp-security" aria-label="Permalink to &quot;WebSocket And MCP Security&quot;">​</a></h2><p>The public market-data proxy requires an API-key authentication message within <code>WS_AUTH_GRACE_SECONDS</code>. Per-client queue size, ping interval, timeout, and subscription capacity are bounded by configuration. Private order, position, and margin topics are not fanned out as public market data.</p><p>Remote MCP is opt-in. Its OAuth boundary implements exact redirect-URI checks, S256-only PKCE, signed access tokens, refresh-token rotation, and token-family revocation after refresh-token reuse. The sample keeps HTTP off but has approval off and write scope enabled if only the master switch is changed; the Docker enable helper applies approval on and write scope off. Write authorization can require fresh TOTP.</p><h2 id="data-protection" tabindex="-1">Data Protection <a class="header-anchor" href="#data-protection" aria-label="Permalink to &quot;Data Protection&quot;">​</a></h2><p>Five SQLite databases and one DuckDB store isolate operational domains; this is not database-wide encryption. Backups must protect all stores together with <code>.env</code>, Fernet material, strategy secrets, and MCP signing keys.</p><table tabindex="0"><thead><tr><th>Store</th><th>Security-relevant contents</th></tr></thead><tbody><tr><td><code>tradeboard.db</code></td><td>Users, hashes, encrypted tokens/API key copy, settings, sessions, OAuth and application state</td></tr><tr><td><code>logs.db</code></td><td>Traffic metadata, login/security trackers, IP bans</td></tr><tr><td><code>latency.db</code></td><td>Timing telemetry</td></tr><tr><td><code>health.db</code></td><td>Runtime health telemetry</td></tr><tr><td><code>sandbox.db</code></td><td>Simulated account and order state</td></tr><tr><td><code>historify.duckdb</code></td><td>Historical market data and Historify metadata</td></tr></tbody></table><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>app.py</code></td><td>Security initialization, CSRF exemptions, headers, teardown</td></tr><tr><td><code>database/user_db.py</code></td><td>Password/TOTP user model</td></tr><tr><td><code>database/auth_db.py</code></td><td>API-key verification, encrypted tokens, sessions</td></tr><tr><td><code>database/traffic_db.py</code></td><td>Traffic and IP security persistence</td></tr><tr><td><code>database/settings_db.py</code></td><td>Persisted automatic-ban settings</td></tr><tr><td><code>utils/security_middleware.py</code></td><td>Pre-Flask ban enforcement</td></tr><tr><td><code>utils/ip_helper.py</code></td><td>Trusted client-IP resolution</td></tr><tr><td><code>utils/session.py</code></td><td>Session-expiry guards</td></tr><tr><td><code>blueprints/security.py</code></td><td>Security dashboard controls</td></tr><tr><td><code>blueprints/mcp_oauth.py</code></td><td>Remote MCP OAuth boundary</td></tr></tbody></table>`,35)])])}const y=t(s,[["render",o]]);export{u as __pageData,y as default};
